package vn.edu.eaut.lab7.controller;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import vn.edu.eaut.lab7.model.SanPham;import vn.edu.eaut.lab7.repository.SanPhamRepository;
@WebServlet("/san-pham") public class SanPhamController extends HttpServlet{
 private final SanPhamRepository r=new SanPhamRepository();
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");String a=q.getParameter("action");if("new".equals(a)){q.getRequestDispatcher("/views/sanpham/form.jsp").forward(q,p);return;}if("edit".equals(a)||"detail".equals(a)){q.setAttribute("sp",r.findById(Integer.parseInt(q.getParameter("id"))));q.getRequestDispatcher("detail".equals(a)?"/views/sanpham/detail.jsp":"/views/sanpham/form.jsp").forward(q,p);return;}if("delete".equals(a)){r.delete(Integer.parseInt(q.getParameter("id")));p.sendRedirect(q.getContextPath()+"/san-pham");return;}q.setAttribute("dsSanPham",r.search(q.getParameter("keyword")));q.getRequestDispatcher("/views/sanpham/list.jsp").forward(q,p);}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{q.setCharacterEncoding("UTF-8");String id=q.getParameter("id");double gia=Double.parseDouble(q.getParameter("gia"));int sl=Integer.parseInt(q.getParameter("soLuong"));if(gia<=0||sl<0){p.sendRedirect(q.getContextPath()+"/san-pham?action=new&error=validate");return;}SanPham x=new SanPham(id==null||id.isBlank()?0:Integer.parseInt(id),q.getParameter("ma"),q.getParameter("ten"),q.getParameter("moTa"),gia,sl);if(x.getId()==0)r.add(x);else r.update(x);p.sendRedirect(q.getContextPath()+"/san-pham");}
}